WITH test_fps AS (SELECT LOWER(REGEXP_REPLACE(COALESCE(instruction,'')||'|'||COALESCE(column_a,'')||'|'||COALESCE(column_b,''),'\s+','','g')) AS fp FROM public.math_questions UNION SELECT LOWER(REGEXP_REPLACE(COALESCE(instruction,'')||'|'||COALESCE(column_a,'')||'|'||COALESCE(column_b,'')||'|'||COALESCE(options::text,'{}'),'\s+','','g')) FROM public.math_test_questions) UPDATE public.practice_questions p SET quality_status='remove', quality_reason = COALESCE(p.quality_reason||';','') || 'duplicate_with_test' FROM test_fps t WHERE LOWER(REGEXP_REPLACE(COALESCE(p.question_data->>'instruction','')||'|'||COALESCE(p.question_data->>'column_a','')||'|'||COALESCE(p.question_data->>'column_b','')||'|'||COALESCE((p.question_data->'options')::text,'{}'),'\s+','','g')) = t.fp AND p.quality_status <> 'remove';